	/**
	 * Default Constructor
	 */
    public TimeSeriesService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new TimeSeriesEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(TimeSeriesRepository.class) );
		this.validator		= applicationContext.getBean(TimeSeriesValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		TimeSeries
	 */
		public TimeSeries createTimeSeries( CreateTimeSeriesCommand command ) {

		TimeSeries entity = new TimeSeries();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setTimeSeriesId( command.getTimeSeriesId() );
            entity.setName( command.getName() );
            entity.setTimezone( command.getTimezone() );
            entity.setGranularity( command.getGranularity() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of TimeSeries {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateTimeSeriesCommand
	 * @return		TimeSeries
	 */
	public TimeSeries updateTimeSeries( UpdateTimeSeriesCommand command ) {

		TimeSeries entity = new TimeSeries();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setTimeSeriesId( command.getTimeSeriesId() );
            entity.setName( command.getName() );
            entity.setTimezone( command.getTimezone() );
            entity.setDatasets( command.getDatasets() );
            entity.setForecasts( command.getForecasts() );
            entity.setAnomalies( command.getAnomalies() );
            entity.setGranularity( command.getGranularity() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of TimeSeries {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteTimeSeriesCommand
	 */
	public void delete( DeleteTimeSeriesCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getTimeSeriesId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of TimeSeries {0} ", id );

	}

	/**
	 * Method to retrieve the TimeSeries via TimeSeriesFetchOneSummary
	 * @param 	summary TimeSeriesFetchOneSummary
	 * @return 	TimeSeriesFetchOneResponse
	 */
	public TimeSeries getTimeSeries( TimeSeriesFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "TimeSeriesFetchOneSummary arg cannot be null" );

		TimeSeries entity = null;
		UUID id = summary.getTimeSeriesId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a TimeSeries using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all TimeSeriess
	 *
	 * @return 	List<TimeSeries>
	 */
    public List<TimeSeries> getAllTimeSeries() {
		List<TimeSeries> list = projector.findAll( new FindAllTimeSeriesQuery() );
		return list;
	}


